export const generateVademecumMedications = (
  branch1: string = 'Sucursal Central (Principal)',
  branch2: string = 'Sucursal 2 (Norte)'
): Medication[] => {
  return VADEMECUM_RAW_CATALOG.map((item, index) => {
    const isUnitOnly = Boolean(item.isUnitOnly || item.unitsPerBox === 1);
    const unitsPerBox = isUnitOnly ? 1 : (item.unitsPerBox || 20);
    const priceBox = item.priceBox || 30.00;
    const costPriceBox = item.costPriceBox || parseFloat((priceBox * 0.65).toFixed(2));
    const priceUnit = isUnitOnly ? priceBox : parseFloat((priceBox / unitsPerBox).toFixed(2));
    const costPriceUnit = isUnitOnly ? costPriceBox : parseFloat((costPriceBox / unitsPerBox).toFixed(2));
    const profitMargin = costPriceBox > 0 ? parseFloat((((priceBox - costPriceBox) / costPriceBox) * 100).toFixed(1)) : 35;

    // Realistic initial stock
    const stockBoxes = isUnitOnly ? 0 : 25;
    const stockUnits = isUnitOnly ? 40 : 25 * unitsPerBox;

    const b1Boxes = isUnitOnly ? 0 : 15;
    const b1Units = isUnitOnly ? 25 : 15 * unitsPerBox;
    const b2Boxes = isUnitOnly ? 0 : 10;
    const b2Units = isUnitOnly ? 15 : 10 * unitsPerBox;

    const lotNumber = makeAutoLot();
    const expiryDate = makeDatePlusYears(2);

    return {
      id: `vdm-${index + 1}-${Date.now().toString().slice(-4)}`,
      name: item.name,
      genericName: item.genericName || item.name,
      laboratory: item.laboratory,
      description: item.description || `Medicamento original de ${item.laboratory}. Presentación ${item.name}.`,
      priceBox,
      priceUnit,
      costPriceBox,
      costPriceUnit,
      profitMarginPercent: profitMargin,
      profitMarginUnitPercent: profitMargin,
      unitsPerBox,
      isUnitOnly,
      category: item.category || Category.OTHERS,
      imageUrl: item.imageUrl || 'https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?q=80&w=400',
      stockBoxes,
      stockUnits,
      branchStock: {
        [branch1]: { boxes: b1Boxes, units: b1Units },
        [branch2]: { boxes: b2Boxes, units: b2Units }
      },
      isControlled: Boolean(item.isControlled),
      minStock: isUnitOnly ? 5 : 3,
      maxStock: isUnitOnly ? 100 : 100,
      batches: [
        {
          lotNumber,
          expiryDate,
          quantity: stockUnits
        }
      ]
    };
  });
};
